@startuml

class Bus {
  + line_number : string
}

class Trajectory {
  + status : string
}

class Line {
  + category : string
}

class ApprovalProcess {
  + status : string
}

class MENSO_Ticket {
  + validity_year : int
}

class Trip {
  + time : time
  + date : date
}

class Invoice {
  + month : int
  + total_amount : double
  + discount : float
}

class Customer {
  + home_address : string
  + office_address : string
  + working_hours : string
}

class MENSO_Card {
  + card_id : string
}

class TicketMachine {
  + registerTrip(time, date, line)
}

class BusCompany {
  + name : string
}

BusCompany "1" -- "*" Bus : owns
BusCompany "1" -- "*" Trajectory : possesses
BusCompany "1" -- "*" Line : manages
BusCompany "1" -- "*" ApprovalProcess : initiates
BusCompany "1" -- "*" Invoice : generates

Trajectory "1" -- "0..*" ApprovalProcess : undergoes
Trajectory "1" -- "0..*" Bus : assigned to
Line "1" -- "*" Trajectory : groups

Line "1" -- "0..*" Trip : associated with
Bus "1" -- "*" Trip : hosts
TicketMachine "1" -- "*" Trip : records

Customer "1" -- "*" Invoice : receives
Customer "1" -- "0..1" MENSO_Card : uses
MENSO_Card "1" -- "*" Trip : validates
Trip "*" -- "0..1" Invoice : included in

@enduml

